The Skip button now calls the existing advanceSession handler and preserves Start, Reset and the daily counter.

<file path="app.js">
(function () {
  'use strict';

  var WORK_SECONDS = 25 * 60;
  var BREAK_SECONDS = 5 * 60;
  var STORAGE_KEY = 'pomodoro.dailyCount';

  var els = {
    app: document.getElementById('app'),
    modeLabel: document.getElementById('mode-label'),
    timer: document.getElementById('timer'),
    toggleBtn: document.getElementById('toggle-btn'),
    resetBtn: document.getElementById('reset-btn'),
    skipBtn: document.getElementById('skip-btn'),
    count: document.getElementById('count')
  };

  var state = {
    mode: 'work',
    remaining: WORK_SECONDS,
    running: false,
    endTime: null,
    count: 0,
    date: todayKey()
  };

  var tickId = null;

  function todayKey() {
    var d = new Date();
    var m = String(d.getMonth() + 1);
    var day = String(d.getDate());
    return d.getFullYear() + '-' + (m.length < 2 ? '0' + m : m) + '-' + (day.length < 2 ? '0' + day : day);
  }

  function loadCount() {
    var count = 0;
    var date = todayKey();
    try {
      var raw = window.localStorage.getItem(STORAGE_KEY);
      if (raw) {
        var data = JSON.parse(raw);
        if (data && data.date === date && typeof data.count === 'number' && data.count >= 0) {
          count = data.count;
        }
      }
    } catch (e) {
      count = 0;
    }
    state.date = date;
    state.count = count;
    saveCount();
  }

  function saveCount() {
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify({ date: state.date, count: state.count }));
    } catch (e) {
      // Storage unavailable; counter still works for this page session.
    }
  }

  function ensureToday() {
    var today = todayKey();
    if (state.date !== today) {
      state.date = today;
      state.count = 0;
      saveCount();
    }
  }

  function durationFor(mode) {
    return mode === 'break' ? BREAK_SECONDS : WORK_SECONDS;
  }

  function secondsLeft() {
    if (state.running && state.endTime !== null) {
      return Math.max(0, Math.ceil((state.endTime - Date.now()) / 1000));
    }
    return state.remaining;
  }

  function formatTime(total) {
    var m = Math.floor(total / 60);
    var s = total % 60;
    return (m < 10 ? '0' + m : String(m)) + ':' + (s < 10 ? '0' + s : String(s));
  }

  function render() {
    var left = secondsLeft();
    var time = formatTime(left);
    var isBreak = state.mode === 'break';
    var label = isBreak ? 'Break' : 'Work session';

    document.documentElement.setAttribute('data-mode', state.mode);
    document.title = time + ' · ' + label + ' · Pomodoro';

    if (els.timer) els.timer.textContent = time;
    if (els.modeLabel) els.modeLabel.textContent = label;
    if (els.count) els.count.textContent = String(state.count);

    if (els.toggleBtn) {
      els.toggleBtn.textContent = state.running ? 'Pause' : 'Start';
      els.toggleBtn.setAttribute('aria-pressed', state.running ? 'true' : 'false');
    }
  }

  function startTicking() {
    if (tickId === null) {
      tickId = window.setInterval(tick, 250);
    }
  }

  function stopTicking() {
    if (tickId !== null) {
      window.clearInterval(tickId);
      tickId = null;
    }
  }

  function start() {
    if (state.running) return;
    state.running = true;
    state.endTime = Date.now() + state.remaining * 1000;
    startTicking();
    render();
  }

  function pause() {
    if (!state.running) return;
    state.remaining = secondsLeft();
    state.running = false;
    state.endTime = null;
    stopTicking();
    render();
  }

  function reset() {
    state.running = false;
    state.endTime = null;
    state.remaining = durationFor(state.mode);
    stopTicking();
    render();
  }

  function advanceSession() {
    ensureToday();
    var nextMode = state.mode === 'work' ? 'break' : 'work';
    state.mode = nextMode;
    state.remaining = durationFor(nextMode);
    if (state.running) {
      state.endTime = Date.now() + state.remaining * 1000;
    } else {
      state.endTime = null;
    }
    render();
  }

  function finishSession() {
    if (state.mode === 'work') {
      state.count += 1;
      saveCount();
      state.mode = 'break';
    } else {
      state.mode = 'work';
    }
    state.remaining = durationFor(state.mode);
    state.endTime = Date.now() + state.remaining * 1000;
    render();
  }

  function tick() {
    ensureToday();
    if (secondsLeft() <= 0) {
      finishSession();
      return;
    }
    render();
  }

  function toggle() {
    if (state.running) {
      pause();
    } else {
      start();
    }
  }

  function onVisibilityChange() {
    if (!document.hidden && state.running) {
      tick();
    }
  }

  function init() {
    loadCount();
    state.remaining = WORK_SECONDS;
    if (els.toggleBtn) els.toggleBtn.addEventListener('click', toggle);
    if (els.resetBtn) els.resetBtn.addEventListener('click', reset);
    if (els.skipBtn) els.skipBtn.addEventListener('click', advanceSession);
    document.addEventListener('visibilitychange', onVisibilityChange);
    render();
  }

  init();
})();
